def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    regions = []
    for ri in range(len(row_bounds) - 1):
        r0, r1 = row_bounds[ri] + 1, row_bounds[ri + 1]
        for ci in range(len(col_bounds) - 1):
            c0, c1 = col_bounds[ci] + 1, col_bounds[ci + 1]
            block = [row[c0:c1] for row in grid[r0:r1]]
            count = sum(v != background for row in block for v in row)
            regions.append((r0, r1, c0, c1, block, count))

    source = max(regions, key=lambda x: x[5])
    if source[5] == 0:
        return grid

    out = [row[:] for row in grid]
    sh, sw = len(source[4]), len(source[4][0])
    for r0, r1, c0, c1, block, count in regions:
        if (r1 - r0, c1 - c0) == (sh, sw):
            for i in range(sh):
                for j in range(sw):
                    out[r0 + i][c0 + j] = source[4][i][j]
    return out
